insert into public.email_automations(id,key,name,trigger_type,is_active) values('c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','course_month-wisdom','Месяц мудрости','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('month-wisdom','Месяц мудрости','practicum','',90,3,5,'c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','416adc90bd9b9a3cd651e9f7ba02d34da19b7979c5cef5342d6f42bf9a68092f') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('1b8e2b8d-18fc-53e4-9ba5-9cda8f5c6031','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Урок 1',1,0,'{Месяц мудрости} Добро пожаловать!','{"ru":"{Месяц мудрости} Добро пожаловать!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с темой мудрости, а точнее с комплексом эмоциональных и телесных состояний, связанных с гармоничностью четвёртой чакры. Мы направим внимание на не только на развитие интеллектуальных качеств (память, логика, анализ...), но и на способность предвидеть, интуичить, сохранять рассудок и спокойствие в моменты яркого эмоционального включения. Внимательно прочитайте это письмо, чтобы понимать, что вас ожидает.</p><p></p><p>1. Расписание совместных практик<br>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке &quot;День&quot;. Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p></p><p>2. Техника безопасности<br>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вам могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p></p><p>3. Ответы на вопросы<br>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p></p><p>4. Ваши регулярные действия - условие результатов<br>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите наполнить жизнь мудростью, осознанностью, сбалансированностью, рассудительностью... Так что поток уже поставлен. Это поток шестой чакры. Входите в этот поток и действуйте - выполняйте асаны, пранаяму, медитацию, а также те поведенческие практики, которые вы наметите на первом уроке. И каждое своё действие совершайте с пониманием, что это ваша практика для гармонизации шестой чакры.</p><p></p><p>5. Первый урок<br>А теперь вы готовы перейти к первому уроку. На этом уроке мы наметим цели и поведенческие практики для каждого участника практикума (ведь для каждого они свои). Очень важно чтобы, планируя месяц движения вперёд, у вас было правильное понимание того внутреннего намерения, которое привело вас на этот практикум. Этот урок посвящен тому, чтобы вы глубже разобрались в том, что такое шестая чакра, почувствовали её энергию, свои ограничения, а также сформулировали лично для себя намерение на этот месяц и наметили связанные с ним практики на каждый день. Длительность урока - 2.5 часа. Рекомендую вам не разбивать урок на части, а пройти его на одном дыхании. Как раз, когда возникает усталость, ощущение перегруза, теряется нить или интерес, и хочется прерваться, рефлексируйте эти моменты, оставаясь в практике.</p><p></p><p>Урок ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>Желаю вам плодотворного месяца!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решились в течение месяца целенаправленно поработать с темой мудрости, а точнее с комплексом эмоци