insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('7867efa7-d83e-51a7-8df9-4c386f5cf012','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Урок 3',3,0,'{Месяц мудрости} Урок 3','{"ru":"{Месяц мудрости} Урок 3"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Предлагаю вам пройти третий урок месяца мудрости. Он посвящён расктытию мудрости на уровне этики, моральных принципов и общего блага. Вас ожидает интересная практика с этим намерением. Длительность урока - 2 часа.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Предлагаю вам пройти третий урок месяца мудрости. Он посвящён расктытию мудрости на уровне этики, моральных принципов и общего блага. Вас ожидает интересная практика с этим намерением. Длительность урока - 2 часа.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Предлагаю вам пройти третий урок месяца мудрости. Он посвящён расктытию мудрости на уровне этики, моральных принципов и общего блага. Вас ожидает интересная практика с этим намерением. Длительность урока - 2 часа.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-wisdom-03','month-wisdom',3,7,'Урок 3','[{"type":"video","vimeoId":"1102466158"}]'::jsonb,'7867efa7-d83e-51a7-8df9-4c386f5cf012') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('fc123961-3e3c-5e55-b685-4440c662d41f','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Дополнительная практика',4,0,'{Месяц мудрости} Дополнительная практика','{"ru":"{Месяц мудрости} Дополнительная практика"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свобоы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свобоы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свобоы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Урок уже ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-wisdom-04','month-wisdom',4,3,'Дополнительная практика','[{"type":"video","vimeoId":"1138990712","practiceId":"1eb05910-efeb-4945-834d-3ae9064c1960"}]'::jsonb,'fc123961-3e3c-5e55-b685-4440c662d41f') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('9c3ad33f-efbc-5246-b6dc-4692cabf96b7','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Урок 4',5,0,'{Месяц мудрости} Урок 4','{"ru":"{Месяц мудрости} Урок 4"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца мудрости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Он ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца мудрости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Он ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца мудрости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока. Он ждёт вас в Гармонизаторе - на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-wisdom-05','month-wisdom',5,4,'Урок 4','[{"type":"video","vimeoId":"1102466233"},{"type":"text","markdown":"ЗАДАНИЕ:\nУчитесь входить в образ разных людей и видеть происходящее их глазами. Экспериментируйте для лучшего взаимопонимания с любимыми людьми, со своим родом, прошлыми жизнями, различными субличностями... Развивайте эмоциональный интеллект."}]'::jsonb,'9c3ad33f-efbc-5246-b6dc-4692cabf96b7') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('cc44270b-8345-5fa0-9caa-d90086841085','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Ещё одна дополнительная практика',6,0,'{Месяц мудрости} Ещё одна дополнительная практика','{"ru":"{Месяц мудрости} Ещё одна дополнительная практика"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию пятой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Данная практика ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию пятой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Данная практика ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию пятой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Данная практика ждёт вас в Гармонизаторе, на вкладке &quot;День&quot;.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-wisdom-06','month-wisdom',6,3,'Ещё одна дополнительная практика','[{"type":"video","vimeoId":"1153479545","practiceId":"9a64c480-e023-4629-9527-43d8d49e11fa"}]'::jsonb,'cc44270b-8345-5fa0-9caa-d90086841085') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('acc7528e-b883-53df-b69c-8eafe16bb09a','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Урок 5',7,0,'{Месяц мудрости} Урок 5','{"ru":"{Месяц мудрости} Урок 5"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию аджны. Этот урок посвящён способности принимать решения. Вас ожидает специальная практика с этим намерением. Длительность урока - 2 час 22 минуты.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>И, так как месяц мудрости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию седьмой чакры - она отвечает за соединённость с тем, что (кто) выше нас. Если первая чакра соединяет нас с Землёй, и даёт физическое здоровье, то седьмая чакра соединяет нас с Небом, и даёт здоровье духовное. Проблема в том, что социум погряз в материализме, в бытовой суете, а религия существенно загрязнена и воспринимается как &quot;опиум для народа&quot;. Поэтому есть над чем поработать. Чтобы ознакомиться с описанием этого месячного практикума и записаться на него, перейдите на страницу - <a href="https://zamkovoi.yoga/m7/">https://zamkovoi.yoga/m7/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию аджны. Этот урок посвящён способности принимать решения. Вас ожидает специальная практика с этим намерением. Длительность урока - 2 час 22 минуты.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>И, так как месяц мудрости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию седьмой чакры - она отвечает за соединённость с тем, что (кто) выше нас. Если первая чакра соединяет нас с Землёй, и даёт физическое здоровье, то седьмая чакра соединяет нас с Небом, и даёт здоровье духовное. Проблема в том, что социум погряз в материализме, в бытовой суете, а религия существенно загрязнена и воспринимается как &quot;опиум для народа&quot;. Поэтому есть над чем поработать. Чтобы ознакомиться с описанием этого месячного практикума и записаться на него, перейдите на страницу - <a href=\"https://zamkovoi.yoga/m7/\">https://zamkovoi.yoga/m7/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию аджны. Этот урок посвящён способности принимать решения. Вас ожидает специальная практика с этим намерением. Длительность урока - 2 час 22 минуты.</p><p></p><p>Урок ждёт вас в Гармонизаторе на вкладке &quot;День&quot;.</p><p></p><p>И, так как месяц мудрости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию седьмой чакры - она отвечает за соединённость с тем, что (кто) выше нас. Если первая чакра соединяет нас с Землёй, и даёт физическое здоровье, то седьмая чакра соединяет нас с Небом, и даёт здоровье духовное. Проблема в том, что социум погряз в материализме, в бытовой суете, а религия существенно загрязнена и воспринимается как &quot;опиум для народа&quot;. Поэтому есть над чем поработать. Чтобы ознакомиться с описанием этого месячного практикума и записаться на него, перейдите на страницу - <a href=\"https://zamkovoi.yoga/m7/\">https://zamkovoi.yoga/m7/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-wisdom-07','month-wisdom',7,4,'Урок 5','[{"type":"video","vimeoId":"1102466379"},{"type":"text","markdown":"#### Что дальше?"},{"type":"video","vimeoId":"1151903876"},{"type":"text","markdown":"Я надеюсь, что этот месяц практик принёс вам ощутимые результаты. И рекомендую вам не терять волну - продолжайте движение в потоке регулярных практик! Посмотрите видео выше, а также перейдите по ссылкам ниже, чтобы сориентироваться в пространстве возможностей, и выбрать то, что для вас окажется наиболее полезным. Возможно, вы решите глубже поработать с состояниями шестой чакры...\n- Интенсив для 6 чакры: https://zamkovoi.yoga/i6/\n- Курс \"36 шагов йоги\": https://zamkovoi.yoga/yoga36/"}]'::jsonb,'acc7528e-b883-53df-b69c-8eafe16bb09a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('8c4e0972-b746-5af3-80a3-a54d20469cea','c8d573b8-9dbf-57ad-a435-76e3ce0fcc69','Завершение практикума',8,0,'{Месяц мудрости} Завершение практикума','{"ru":"{Месяц мудрости} Завершение практикума"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию шестой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность к состояниям этой чакры, в значительной степени очистили её и гармонизировали, а также наработали навык пранаямы. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>Так как Месяц мудрости закончился, предлагаю вам на волне благодарностью отпустить все обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>И, если вы ещё не записались на практики следующего месяца, направленные на гармонизацию седьмой чакры, то можете сделать это, перейдя по ссылке - <a href="https://zamkovoi.yoga/m7/">https://zamkovoi.yoga/m7/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие шестой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив для 6 чакры: <a href="https://zamkovoi.yoga/i6/">https://zamkovoi.yoga/i6/</a><br>- Курс &quot;36 шагов йоги&quot;: <a href="https://zamkovoi.yoga/yoga36/">https://zamkovoi.yoga/yoga36/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif\" alt=\"Месяц мудрости\" width=\"504\" height=\"155\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию шестой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность к состояниям этой чакры, в значительной степени очистили её и гармонизировали, а также наработали навык пранаямы. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>Так как Месяц мудрости закончился, предлагаю вам на волне благодарностью отпустить все обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>И, если вы ещё не записались на практики следующего месяца, направленные на гармонизацию седьмой чакры, то можете сделать это, перейдя по ссылке - <a href=\"https://zamkovoi.yoga/m7/\">https://zamkovoi.yoga/m7/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие шестой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив для 6 чакры: <a href=\"https://zamkovoi.yoga/i6/\">https://zamkovoi.yoga/i6/</a><br>- Курс &quot;36 шагов йоги&quot;: <a href=\"https://zamkovoi.yoga/yoga36/\">https://zamkovoi.yoga/yoga36/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-completion-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Вот и завершился месяц практик, направленных на гармонизацию шестой чакры. Я надеюсь, что этот месяц был для вас плодотворен, что вы развили осознанность к состояниям этой чакры, в значительной степени очистили её и гармонизировали, а также наработали навык пранаямы. Продолжайте практиковать и делать жизнь ещё лучше!</p><p></p><p>Так как Месяц мудрости закончился, предлагаю вам на волне благодарностью отпустить все обещания, которые в связи с этим практикумом вы могли давать мне или я давал вам. Они вас поддерживали, но более не нужны и свободны. Если какие-то обещания вы давали сами себе, но не выполнили (например, не практиковали в должной мере), предлагаю вам себя простить, и всё это также отпустить. Вы сделали лучшее, на что способны. Движемся дальше на легке :)</p><p></p><p>И, если вы ещё не записались на практики следующего месяца, направленные на гармонизацию седьмой чакры, то можете сделать это, перейдя по ссылке - <a href=\"https://zamkovoi.yoga/m7/\">https://zamkovoi.yoga/m7/</a></p><p></p><p>Хотя, я не удивлюсь, если вы предпочтёте углубиться в развитие шестой чакры, и запишитесь на соответствующий интенсив или курс. Уж очень интересные плоды находятся на этом уровне :)<br>- Интенсив для 6 чакры: <a href=\"https://zamkovoi.yoga/i6/\">https://zamkovoi.yoga/i6/</a><br>- Курс &quot;36 шагов йоги&quot;: <a href=\"https://zamkovoi.yoga/yoga36/\">https://zamkovoi.yoga/yoga36/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
